function setLeadStatus(id,status,reason){need('leads.manage');var l=lead(id);if(!l)fail('Lead not found.');if(status==='converted')fail('Use Convert to Story so the story is linked to this lead.');if(l.status==='converted')fail('This lead is already linked to a story.');var label=LEAD_STAGES.filter(function(s){return s.k===status;})[0].label;l.status=status;if(reason!=null)l.reason=reason;l.timeline.unshift({at:nowIso(),text:'Moved to '+label});log('Moved lead to '+label,person(l.personId).name);save();}
