/* ---------- calendar ---------- */
var bookingPitch=false;
function overlaps(a,b){return new Date(a.start)<new Date(b.end)&&new Date(b.start)<new Date(a.end);}
function conflicts(ev){return state.events.filter(function(x){return x.id!==ev.id&&x.status!=='cancelled'&&x.type!=='deadline'&&overlaps(x,ev)&&x.attendees.some(function(a){return (ev.attendees||[]).indexOf(a)>=0;});});}
