function pitchSlots(days){var av=state.availability,out=[],base=new Date(),owner=av.ownerId;for(var i=0;i<(days||14);i++){var d=new Date(base.getTime()+i*864e5),ymd=ymdIn(d,av.tz),wd=new Date(ymd+'T12:00:00Z').getUTCDay(),win=av.overrides[ymd]||av.weekly[wd]||[];win.forEach(function(w){var s=zoned(ymd,w[0],av.tz),e=zoned(ymd,w[1],av.tz);for(var t=s.getTime();t+av.slotMin*6e4<=e.getTime();t+=av.slotMin*6e4){var sl={start:new Date(t).toISOString(),end:new Date(t+av.slotMin*6e4).toISOString(),attendees:[owner]};if(t>Date.now()&&!conflicts(sl).length)out.push(sl);}});}return out;}
function bookPitch(storyId,slot){need('calendar.manage');var s=story(storyId);if(!s)fail('Story not found.');if(!s.pitch.submitted)fail('Submit the Pitch Sheet before booking a pitch.');if(!pitchSlots(21).some(function(x){return x.start===slot.start;}))fail('That time was just taken. Please choose another slot.');if(!canSee(s))fail('This story is not available to your role.');bookingPitch=true;var ev;try{ev=saveEvent({type:'pitch',title:'Pitch: '+s.title,start:slot.start,end:slot.end,attendees:[state.availability.ownerId,s.producerId],storyId:s.id,prodId:s.prodId});}finally{bookingPitch=false;}s.stage='pitch_review';storyActivity(s,'Pitch booked with Culture Lab');save();return ev;}

