function createDelivery(d){need('delivery.build');var n=state.deliveries.filter(function(x){return x.prodId===d.prodId&&x.seasonId===d.seasonId;}).length+1;var o={id:uid('nd'),prodId:d.prodId,seasonId:d.seasonId,name:d.name||'Network Delivery '+n,stories:[],status:'draft',approvedBy:null,sentBy:null,sentAt:null,due:d.due||null,email:{to:'Network Development',subject:'',body:''},snapshot:[]};state.deliveries.unshift(o);log('Created network delivery',o.name);save();return o;}
