function isMail(v){return /^\S+@\S+\.\S+$/.test(String(v||''));}
/* ---------- file policy: which files can be uploaded, and how large. Checked in the browser, on the server and by the storage bucket. ---------- */
var FILE_KINDS=[
  {kind:'Video',max:2147483648,ext:{mp4:'video/mp4',mov:'video/quicktime',m4v:'video/x-m4v',webm:'video/webm'}},
  {kind:'Audio',max:524288000,ext:{mp3:'audio/mpeg',m4a:'audio/mp4',wav:'audio/wav',aac:'audio/aac'}},
  {kind:'Image',max:52428800,ext:{jpg:'image/jpeg',jpeg:'image/jpeg',png:'image/png',heic:'image/heic',heif:'image/heif',webp:'image/webp',gif:'image/gif'}},
  {kind:'Document',max:104857600,ext:{pdf:'application/pdf',doc:'application/msword',docx:'application/vnd.openxmlformats-officedocument.wordprocessingml.document',txt:'text/plain',rtf:'application/rtf',csv:'text/csv',xls:'application/vnd.ms-excel',xlsx:'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet',ppt:'application/vnd.ms-powerpoint',pptx:'application/vnd.openxmlformats-officedocument.presentationml.presentation'}}];
function fileCheck(name,size){var m=/\.([a-z0-9]{1,5})$/i.exec(String(name||'')),ext=m?m[1].toLowerCase():'',k=FILE_KINDS.filter(function(x){return x.ext[ext];})[0];
  if(!k)return {ok:false,error:'That file type is not allowed. Upload video (MP4, MOV), audio (MP3, M4A, WAV), images (JPG, PNG, HEIC) or documents (PDF, Word, Excel, PowerPoint, text).'};
  var n=+size;if(!(n>0))return {ok:false,error:'That file is empty.'};if(n>k.max)return {ok:false,error:k.kind+' files can be up to '+Math.round(k.max/1048576)+' MB. This one is '+Math.round(n/1048576)+' MB.'};
  return {ok:true,kind:k.kind,mime:k.ext[ext]};}
/* ---------- rules engine: timed rules, prep tasks, repeating meetings and task links ---------- */
var PRIORITY={high:'High',normal:'Normal',low:'Low'},REPEAT={daily:'Daily',weekdays:'Every weekday',weekly:'Weekly',biweekly:'Every 2 weeks',monthly:'Monthly'};
var PREP={interview:[['Prepare interview questions',1],['Confirm the interview with the participant',2]],pitch:[['Finalize pitch materials',1]]};
function ruleOf(a){var r={k:a[0],trigger:a[0],action:a[1],on:true};if(a[2])r.cfg=clone(a[2]);return r;}
function rule(k){return (state.automations||[]).filter(function(a){return a.k===k;})[0]||null;}
function ruleOn(k){var r=rule(k);return !r||!!r.on;}
function ruleCfg(k,f,def){var r=rule(k),v=r&&r.cfg?+r.cfg[f]:NaN;return isFinite(v)&&v>0?v:def;}
function ruleRun(trigger,action,ref){state.automationLog.unshift({id:uid('r'),at:nowIso(),trigger:trigger,action:action,ok:true,ref:ref||''});state.automationLog=state.automationLog.slice(0,300);}
function ensureRules(){if(!Array.isArray(state.automations))state.automations=[];AUTOMATIONS.forEach(function(a){var r=rule(a[0]);if(!r)state.automations.push(ruleOf(a));else if(a[2]&&!r.cfg)r.cfg=clone(a[2]);});}
function leadsFor(exclude){return state.users.filter(function(x){return x.active&&x.id!==exclude&&x.role!=='network_reviewer'&&(can('productions.manage',x)||can('final.review',x));});}
function validDue(v){if(v==null||v==='')return null;var d=new Date(v);if(isNaN(d))fail('Choose a valid due date.');return d.toISOString();}
function openBlockers(t){return (t.blockedBy||[]).map(function(id){return find('tasks',id);}).filter(function(x){return x&&x.status==='open';});}
function setBlockers(t,list){var ids=[];(Array.isArray(list)?list:[]).slice(0,10).forEach(function(id){var x=find('tasks',id);if(!x||x.id===t.id||ids.indexOf(x.id)>=0)return;ids.push(x.id);});
  var reaches=function(from,seen){if(from===t.id)return true;if(seen[from])return false;seen[from]=1;var x=find('tasks',from);return !!x&&(x.blockedBy||[]).some(function(n){return reaches(n,seen);});};
  ids.forEach(function(id){if(reaches(id,{}))fail('That would make these tasks wait on each other.');});t.blockedBy=ids;}
function prepDue(start,off){var st=new Date(start).getTime(),now=Date.now(),d=st-off*6e4;if(d<now+30*6e4)d=Math.min(st,now+30*6e4);return new Date(d).toISOString();}
function prepFor(ev){if(!PREP[ev.type]||!ev.storyId)return;var s=story(ev.storyId);if(!s)return;var h=ruleCfg('Meeting scheduled','hours',24),pu=s.producerId&&user(s.producerId),owner=pu&&pu.active?pu.id:(me()?me().id:null);
  auto('Meeting scheduled',function(){var n=0;PREP[ev.type].forEach(function(p){var off=p[1]*h*60;task({title:p[0]+': '+s.title,assignee:owner,due:prepDue(ev.start,off),storyId:s.id,source:'Automation',eventId:ev.id,offsetMin:off,priority:'high',blockedBy:[]});n++;});return 'Created '+n+' prep task'+(n===1?'':'s')+' for '+ev.title;},s.title);}
