function noteVisible(n,u){return n.by===u.id||n.mentions.indexOf(u.id)>=0||can('stories.all',u)||n.links.some(function(l){return l.type==='story'&&story(l.id)&&canSee(story(l.id),u);});}

/* ---------- what each signed-in role is allowed to receive ---------- */
