function rowsToState(rows){var s={};LIST.forEach(function(k){s[k]=[];});rows.forEach(function(r){if(r.c==='meta')s[r.id]=r.data;else if(s[r.c])s[r.c].push(r.data);});NEWEST.forEach(function(k){s[k].sort(function(a,b){return String(b.at||'').localeCompare(String(a.at||''));});});return s;}
