  function resolve(state,identity){var e=String(identity.email||'').trim().toLowerCase(),u=state.users.filter(function(x){return String(x.email||'').trim().toLowerCase()===e;})[0];if(!u&&state.users.length===1&&!state.users[0].lastSeen)throw new HttpError(403,'not_staff','This email does not match the owner email set in Supabase (CULTURE_LAB_OWNER_EMAIL). Check the secret, then redeploy the function.');if(!u||!u.active)throw new HttpError(403,'not_staff','This account does not have portal access.');if(u.mfa&&identity.aal!=='aal2')throw new HttpError(403,'mfa_required','Multifactor authentication is required.');return u.id;}
